import pytest
from attr import define, FrozenInstanceError

@define(frozen=True)
class MyException(Exception):
    message: str

def test_frozen_exception_mutation():
    exc = MyException(message="test")

    # These should be allowed (current behavior)
    exc.__cause__ = Exception("cause")
    exc.__context__ = Exception("context")
    exc.__traceback__ = Exception("traceback")

    # These should be allowed (requested behavior)
    # Currently they should raise FrozenInstanceError
    try:
        exc.__suppress_context__ = True
    except FrozenInstanceError:
        print("Caught expected FrozenInstanceError for __suppress_context__")
    except Exception as e:
        pytest.fail(f"Unexpected exception type: {type(e)}")

    try:
        exc.__notes__ = "some notes"
    except FrozenInstanceError:
        print("Caught expected FrozenInstanceError for __notes__")
    except Exception as e:
        pytest.fail(f"Unexpected exception type: {type(e)}")

if __name__ == "__main__":
    # Run as a simple script for now to verify
    try:
        test_frozen_exception_mutation()
        print("Test finished successfully (caught expected errors)")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e

